import { request } from "@/utils/index"
import appStore from '@/store/app'
/**
 * 获取字典
 * @param name
 */
export const getDict = (dictKey) => {
  return new Promise((resolve) => {
    if (appStore.hasDict(dictKey)) {
      resolve(appStore.getDict(dictKey))
      return
    }
    request({
      method: 'GET',
      url: `system/dictData/listByType/${dictKey}`
    }).then(({ data }) => {
      const arr = data.map((item) => {
        return {
          color: item.listClass,
          remark: item.remark,
          text: item.dictLabel,
          label: item.dictLabel,
          value: item.dictValue,
        }
      })
      appStore.setDict(dictKey, arr)
      resolve(arr)
    })
  })
}

