 * @param name busCode对应名称 见上方busCodes
 * @param id 主键id
 */
export const getFiles = async (name, id) => {
  const { data } = await request({
    method: 'POST',
    url: 'file/appendix/listAppendixPackage',
    data: {
      busCode: busCodes[name],
      busId: id,
    }
  })
  return data
    .map(
      (el) => el.appendices?.map((item) => ({
        ...item,
        rawData: item.fileSite || item.fileThumbnailSite,
        filePath: item.fileSite,
        fileName: item.fileName,
      })) || []
    )
    .flat()
}

